#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The Pi session wizard (#25): one platform plan on the Pi, from the laptop, with no agent in the loop.
#
#   bash pi/wizard.sh [plan]          plan: default plans/pi5-speedtest.json; next plans/pi5-fullcell.json
#                                     an energy plan ("mode": "energy", #26) runs the same way; it has nothing to score
#
# Run it from Git Bash on the laptop. Every stage finds what is already done (the connection, the files on the Pi,
# the install, a session that is running or complete), so run it again at any time: it picks up where things are.
# The session itself runs on the Pi under nohup, so closing the wizard or losing SSH does not stop it.
# Rehearsal only (pi/tests/rehearse.sh): WIZ_SSH stands in for ssh, WIZ_DRY_RUN=1 adds the runner's --dry-run,
# and WIZ_RESULTS is where the results come home to (default study/).

run_wizard() {

TOTAL_STAGES=7

STUDY="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$STUDY"
[[ "$ENV_FILE" == ".env" ]] && ENV_FILE="$STUDY/pi/.env"
PLAN="${1:-plans/pi5-speedtest.json}"
SSH_BIN="${WIZ_SSH:-ssh}"
DRY="${WIZ_DRY_RUN:-}"
RESULTS="${WIZ_RESULTS:-$STUDY}"
PI_DIR="uav/study"   # on the Pi, under its home
PI_VENV="sb"         # PLATFORMS.md's venv, under the Pi's home
LPY=python3
for p in .venv/Scripts/python.exe .venv/bin/python; do [[ -x "$p" ]] && { LPY="$STUDY/$p"; break; }; done

die() { warn "$1"; exit 1; }
LOST="lost the connection to the Pi (a session there keeps running): run the wizard again"
[[ -f "$PLAN" ]] || die "no plan at study/$PLAN"
lpy() { "$LPY" "$@" | tr -d '\r'; }
PLATFORM=$(lpy -c 'import json, sys; print(json.load(open(sys.argv[1]))["platform"])' "$PLAN")
NOTE=$(lpy -c 'import json, sys; print(json.load(open(sys.argv[1])).get("note") or "")' "$PLAN")
MODE=$(lpy -c 'import json, sys; print(json.load(open(sys.argv[1])).get("mode") or "latency")' "$PLAN")
OUT="bench/$PLATFORM/$(basename "$PLAN" .json)"   # the runner's default --out
NEEDS=()
while IFS= read -r p; do NEEDS+=("$p"); done < <(lpy scripts/studysession.py "$PLAN" --needs)
(( ${#NEEDS[@]} )) || die "the plan is not valid: see above"

# pi CMD runs CMD on the Pi with no stdin; pi_in keeps stdin (tar); pi_sh runs the script on stdin there, in the study
# folder, with PLAN, OUT and PY (the venv's python) set, and its own arguments as $1, $2...
pi()    { "$SSH_BIN" -n -o ConnectTimeout=10 -o ServerAliveInterval=30 "$PI_USER@$PI_HOST" "$@"; }
pi_in() { "$SSH_BIN" -o ConnectTimeout=10 -o ServerAliveInterval=30 "$PI_USER@$PI_HOST" "$@"; }
pi_sh() {
  { printf 'PLAN=%q OUT=%q PY="$HOME/%s/bin/python"\n' "$PLAN" "$OUT" "$PI_VENV"
    printf 'mkdir -p "$HOME/%s" && cd "$HOME/%s" || exit 1\n' "$PI_DIR" "$PI_DIR"
    cat; } | pi_in "bash -s -- $(printf '%q ' "$@")" | tr -d '\r'
}
next() { pause "Press Enter for the next stage"; }
# The same one-hash-over-every-file-under-a-path, on the laptop (tree_hash) and on the Pi (TREE_HASH, for pi_sh)
TREE_HASH='LC_ALL=C find "$1" -type f -print0 | LC_ALL=C sort -z | xargs -0 sha256sum | sed -E "s/^([0-9a-f]{64}) [ *]/\1  /" | sha256sum | cut -c1-64'
tree_hash() { bash -c "$TREE_HASH" _ "$1"; }
pi_hash()   { printf '[ -e "$1" ] || { echo missing; exit 0; }\n%s\n' "$TREE_HASH" | pi_sh "$1"; }
free_gb() {
  if command -v powershell.exe >/dev/null 2>&1; then
    powershell.exe -NoProfile -Command "[math]::Round((Get-CimInstance Win32_OperatingSystem).FreePhysicalMemory/1MB,1)" | tr -d '\r'
  else awk '/MemAvailable/ {printf "%.1f\n", $2 / 1048576}' /proc/meminfo; fi
}

banner "Pi session: $(basename "$PLAN" .json) on the $PLATFORM"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "What you need ready"
say "Plan:    study/$PLAN"
[[ -n "$NOTE" ]] && say "         $NOTE"
say "Results: study/$OUT (on the Pi, then on this laptop)"
[[ "$MODE" == energy ]] && note "An energy session (#26): per cell, a 1-minute idle reading, then 3 minutes with the PMIC read. No latency, nothing to score."
printf '\n'
say "Have these ready before you go on:"
step "The Pi 5 on its official 27 W USB-C supply, with the Active Cooler fitted, on this laptop's network (or Tailscale)."
step "Its host name or IP address, and the user you log in as."
step "SSH on (raspi-config → Interface Options → SSH). Stage 2 sets up a key from this laptop if there is none."
step "The Pi's password, for the key and for sudo (the one-time setup fixes in stage 5)."
step "Is the install done (~/$PI_VENV with the pinned packages)? If not, stage 5 does it: it needs internet on the Pi, about 10 min."
note "The Pi stays with us until 31 October: the install is done once, and later runs of this wizard skip what is done."
confirm "Is all of that ready?" || { say "Run the wizard again when it is."; exit 0; }

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Connect to the Pi"
ask PI_HOST "The Pi's host name or IP (e.g. raspberrypi.local):"
ask PI_USER "The user on the Pi (e.g. pi):"
write_env PI_HOST "$PI_HOST"
write_env PI_USER "$PI_USER"
key_ok() { "$SSH_BIN" -n -o BatchMode=yes -o ConnectTimeout=10 "$PI_USER@$PI_HOST" true 2>/dev/null; }
if key_ok; then
  say "SSH with a key works."
else
  warn "SSH without a password does not work yet."
  if [[ ! -f "$HOME/.ssh/id_ed25519.pub" ]] && confirm "Make an SSH key on this laptop (~/.ssh/id_ed25519, no passphrase)?"; then
    ssh-keygen -t ed25519 -N "" -f "$HOME/.ssh/id_ed25519"
  fi
  say "Copying the key to the Pi: type the Pi's password when ssh asks."
  ssh-copy-id -i "$HOME/.ssh/id_ed25519.pub" "$PI_USER@$PI_HOST" || true
  key_ok || die "still no SSH: check the host and user, that SSH is on, and that the Pi is on this network; then run the wizard again"
  say "SSH with a key works now."
fi
MODEL=$(pi "tr -d '\\0' < /proc/device-tree/model 2>/dev/null; echo; uname -m" | tr -d '\r' | paste -sd ' ' -) || die "$LOST"
say "The Pi says: $MODEL"
if [[ "$PLATFORM" == pi5 && "$MODEL" != *"Raspberry Pi 5"* ]]; then
  warn "this plan is for a Pi 5, and this board is not one."
  confirm "Go on anyway?" || exit 1
fi
next

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Fan, power and SD card"
HW=$(pi_sh <<'EOF'
echo "fan_rpm=$(cat /sys/devices/platform/cooling_fan/hwmon/hwmon*/fan1_input 2>/dev/null | head -n1)"
echo "temp=$(vcgencmd measure_temp 2>/dev/null | cut -d= -f2)"
echo "throttled=$(vcgencmd get_throttled 2>/dev/null | cut -d= -f2)"
echo "free_bytes=$(df -Pk "$HOME" | awk 'NR == 2 {print $4 * 1024}')"
EOF
) || die "$LOST"
hw() { printf '%s\n' "$HW" | sed -n "s/^$1=//p"; }
if [[ "$PLATFORM" == pi* ]]; then
  FAN=$(hw fan_rpm)
  if [[ -z "$FAN" ]]; then
    warn "no fan found. The firmware turns the fan on only if it spins at boot: check that the Active Cooler's cable is in the FAN"
    warn "socket, then reboot the Pi. Without the fan the Pi throttles, and its cells are re-run."
    confirm "Go on without a fan?" || exit 1
  else
    say "Fan: about $FAN rpm (0 is normal below 50 C: it starts at 50 C and is at full speed by 75 C)."
  fi
  say "CPU: $(hw temp)"
  T=$(hw throttled)
  if [[ -z "$T" ]]; then
    warn "vcgencmd get_throttled is unreadable."
  elif (( T == 0 )); then
    say "Power and throttling: clean (get_throttled $T)."
  else
    (( T & 0x10001 )) && warn "under-voltage seen ($T): use the official 27 W supply, or the cells throttle."
    (( T & 0xE000E )) && warn "throttling or a frequency cap seen ($T)."
    note "Bits 16-19 stay set until a reboot. The runner checks every cell, so a clean reboot is the simplest fix."
    confirm "Go on anyway?" || exit 1
  fi
fi
FREE=$(hw free_bytes); FREE=${FREE:-0}
say "SD card: $(( FREE >> 20 )) MB free (stage 4 checks it against what must be copied)."
next

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Copy the scripts, the exports, the images and the plan"
for p in "${NEEDS[@]}"; do [[ -e "$p" ]] || die "missing on this laptop: study/$p (make an export with scripts/studyexport.py)"; done
tar -cf - scripts/studybench.py scripts/studysession.py "$PLAN" | pi_in "mkdir -p \"\$HOME/$PI_DIR\" && tar -xf - -C \"\$HOME/$PI_DIR\"" \
  || die "$LOST"
say "Copied the scripts and the plan (small: always copied)."
declare -A HASH=()
TO_COPY=()
for p in "${NEEDS[@]}"; do
  HASH[$p]=$(tree_hash "$p")
  there=$(pi_hash "$p") || die "$LOST"
  if [[ "$there" == "${HASH[$p]}" ]]; then say "already there: $p"; else TO_COPY+=("$p"); fi
done
if (( ${#TO_COPY[@]} )); then
  NEED=$(( $(du -scb "${TO_COPY[@]}" | tail -n1 | cut -f1) + (1 << 30) ))   # and 1 GB for the results: a full cell's detections are about 150 MB
  say "To copy: ${TO_COPY[*]}"
  say "That needs up to $(( NEED >> 20 )) MB on the SD card, with the results; $(( FREE >> 20 )) MB are free."
  (( FREE >= NEED )) || warn "not enough space on the SD card."
  note "A path that differs at all is copied again whole, so an interrupted copy starts over."
  confirm "Copy now?" || exit 0
fi
for p in ${TO_COPY[@]+"${TO_COPY[@]}"}; do
  say "copying $p ($(du -sh "$p" | cut -f1))..."
  tar -cf - "$p" | pi_in "cd \"\$HOME/$PI_DIR\" && rm -rf $(printf '%q' "$p") && tar -xf -" || die "the copy of $p failed: run the wizard again"
  [[ "$(pi_hash "$p")" == "${HASH[$p]}" ]] || die "the copy of $p on the Pi differs from the laptop's: run the wizard again"
  say "  copied and checked."
done
next

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Install and setup checks"
if pi "test -x \"\$HOME/$PI_VENV/bin/python\""; then
  say "The install is there (~/$PI_VENV)."
else
  PINS=$(lpy -c "import sys; sys.path.insert(0, 'scripts'); import studysession as s; print(' '.join(f'{k}=={v}' for k, v in s.PI_PINS.items()))")
  NCNN=$(printf '%s\n' $PINS | grep '^ncnn==')
  PINS=$(printf '%s\n' $PINS | grep -v '^ncnn==' | paste -sd ' ' -)
  say "No install yet. It makes ~/$PI_VENV and installs PLATFORMS.md's pins:"
  note "  $PINS"
  note "  $NCNN (with --no-deps: it would pull in opencv-python, which clashes with the headless build)"
  confirm "Install now (needs internet on the Pi, about 10 min)?" || exit 1
  pi "python3 -m venv \"\$HOME/$PI_VENV\" && \"\$HOME/$PI_VENV/bin/pip\" install $PINS && \"\$HOME/$PI_VENV/bin/pip\" install --no-deps $NCNN" \
    || die "the install failed: see pip's output above"
fi
PI_OVERRIDE=""
while :; do
  CHECK=$(pi_sh <<'EOF'
"$PY" scripts/studysession.py "$PLAN" --check; echo "rc=$?"
EOF
) || die "$LOST"
  printf '%s\n' "$CHECK" | grep -v '^rc=' | sed 's/^/  /'
  [[ "$CHECK" == *"rc=0"* ]] && break
  FIXES=()
  while IFS= read -r f; do FIXES+=("$f"); done < <(printf '%s\n' "$CHECK" | sed -n 's/^ *fix: //p')
  (( ${#FIXES[@]} )) || die "the check itself failed on the Pi (see its output above), not a setup check: fix that, then run the wizard again"
  say "Some checks failed. Their fixes, to run on the Pi (sudo asks for the Pi's password):"
  for f in "${FIXES[@]}"; do note "  $f"; done
  note "The governor fix lasts until the next reboot; the runner checks it at every start."
  if confirm "Run these fixes on the Pi now?"; then
    for f in "${FIXES[@]}"; do "$SSH_BIN" -t "$PI_USER@$PI_HOST" "PATH=\"\$HOME/$PI_VENV/bin:\$PATH\"; $f" || warn "this fix failed: $f"; done
    continue
  fi
  ask PI_OVERRIDE "Run anyway? Then give the reason, which the session records (empty stops here):"
  [[ -n "$PI_OVERRIDE" ]] || { say "Fix them, then run the wizard again."; exit 1; }
  break
done
next

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Run the session on the Pi"
session_status() { pi_sh <<'EOF'
pid=$(cat "$OUT/runner.pid" 2>/dev/null)
if [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null && tr '\0' ' ' < "/proc/$pid/cmdline" 2>/dev/null | grep -q studysession; then
  echo running
elif [ -f "$OUT/session.json" ]; then
  s=$("$PY" -c 'import json, sys; print(json.load(open(sys.argv[1])).get("status"))' "$OUT/session.json")
  [ "$s" = running ] && s=stopped   # its runner is gone (a power cut, a kill): the same command resumes it
  echo "$s"
else
  echo new
fi
EOF
}
show_progress() { pi_sh <<'EOF'
[ -f "$OUT/summary.csv" ] && "$PY" - "$OUT/summary.csv" <<'PROGRESS'
import csv, sys
with open(sys.argv[1], newline="", encoding="utf-8") as f:
    rows = list(csv.DictReader(f))
value = "rail_j_per_frame" if rows and "rail_j_per_frame" in rows[0] else "latency_ms"  # an energy summary, or a latency one
for r in [{"cell": "cell", "outcome": "outcome", value: value, "throttle": "throttle"}, *rows]:
    print(f"  {r['cell']:<42} {r['outcome']:<14} {r[value]:<16} {r['throttle']}")
PROGRESS
echo; tail -n 8 "$OUT/session.log" 2>/dev/null | cut -c1-160
EOF
}
start_session() { pi_sh "$DRY" "$PI_OVERRIDE" <<'EOF'
mkdir -p "$OUT"
args=(); [ -n "$1" ] && args+=(--dry-run); [ -n "$2" ] && args+=(--override-checks "$2")
S=; command -v setsid >/dev/null && S=setsid
nohup $S "$PY" -u scripts/studysession.py "$PLAN" --out "$OUT" "${args[@]}" >> "$OUT/runner.out" 2>&1 < /dev/null &
echo $! > "$OUT/runner.pid"
EOF
}
ST=$(session_status) || die "$LOST"
case "$ST" in
  complete) say "This session is already complete on the Pi." ;;
  running)  say "This session is running on the Pi." ;;
  new)      say "No session of this plan on the Pi yet."
            confirm "Start it now?" || exit 0
            start_session; sleep 3 ;;
  *)        say "The session on the Pi is $ST: starting it again resumes it (finished runs are kept)."
            [[ "$ST" == refused ]] && note "A setup check refused it; stage 5 has just run the checks again."
            confirm "Resume it now?" || exit 0
            start_session; sleep 3 ;;
esac
while :; do
  ST=$(session_status) || die "$LOST"
  _clear
  printf '\n%s%s▸ Stage %s/%s · %s%s\n\n' "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "Run the session on the Pi: $ST" "$RESET"
  show_progress
  [[ "$ST" == running ]] || break
  printf '\n'
  note "It refreshes every 30 s. Type l and Enter to leave it running and close the wizard; Ctrl-C does the same."
  rc=0; read -r -t 30 key || rc=$?
  if (( rc == 0 )); then
    [[ "$key" == l ]] && { say "It keeps running on the Pi. Run the wizard again to come back: bash pi/wizard.sh $PLAN"; exit 0; }
  elif (( rc <= 128 )); then
    sleep 30   # no terminal input left (a rehearsal): wait anyway
  fi
done
if [[ "$ST" != complete ]]; then
  warn "the session stopped as $ST. The runner's last words:"
  pi_sh <<'EOF' | sed 's/^/    /'
tail -n 15 "$OUT/runner.out" 2>/dev/null
EOF
  die "fix what it says, then run the wizard again: it resumes the session"
fi
say "The session is complete."
next

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Copy the results home, and score them"
mkdir -p "$RESULTS"
confirm "Copy the results home$([[ "$MODE" == energy ]] || printf ' and score them') now?" || { say "Run the wizard again to do it later."; exit 0; }
pi "cd \"\$HOME/$PI_DIR\" && tar -cf - $(printf '%q' "$OUT")" | tar -xf - -C "$RESULTS" || die "$LOST"
say "Copied to $RESULTS/$OUT"
SUMMARY="$RESULTS/$OUT/summary.csv"
command -v cygpath >/dev/null 2>&1 && SUMMARY=$(cygpath -m "$SUMMARY")
if [[ "$MODE" == energy ]]; then
  say "An energy session has nothing to score. Its summary, in W and J of the PMIC rail sum, not wall power:"
  lpy - "$SUMMARY" <<'ENERGY' | column -t -s $'\t' | sed 's/^/    /'
import csv, json, sys
from pathlib import Path
cols = ("cell", "outcome", "sampler", "fps", "rail_idle_w", "rail_run_w", "rail_j_per_frame", "rail_j_per_frame_net", "throttle")
with open(sys.argv[1], newline="", encoding="utf-8") as f:
    rows = list(csv.DictReader(f))
for r in [dict(zip(cols, cols)), *rows]:
    print("\t".join(r[k] or "-" for k in cols))
c = json.loads((Path(sys.argv[1]).parent / "session.json").read_text(encoding="utf-8"))["sampler_cost"]
print("\nthe sampler's cost on FPS:\t" + (f"{c['cost_pct']:+.1f}% ({c['fps_sampler_on']} FPS with it, {c['fps_sampler_off']} without)"
                                         if c["cost_pct"] is not None else "unknown: a run of the pair failed"))
ENERGY
  note "J per frame is compared within the Pi 5 only, never across platforms (#8); the net figure subtracts the idle reading."
  next
  finish
  return
fi
# The summary read by its column names, and the reference runs by studysession's own names
INFO=$(lpy - "$SUMMARY" <<'PY'
import csv, sys
sys.path.insert(0, "scripts")
import studysession as s
with open(sys.argv[1], newline="", encoding="utf-8") as f:
    rows = list(csv.DictReader(f))
cells = [r for r in rows if r["cell"] not in s.DRIFT_UNITS]
print("drift=" + (rows[0]["drift"] if rows else "unknown"))
print("full=%d" % sum(r["images"] == "all" for r in cells))
for r in cells:
    if r["run_dir"]:
        print("run=" + r["run_dir"])
for r in [dict(zip(rows[0], rows[0])), *rows] if rows else []:
    print("row=" + "\t".join(r[k] for k in ("cell", "images", "outcome", "latency_ms", "latency_source", "throttle", "drift")))
PY
)
RUNS=()
while IFS= read -r r; do RUNS+=("$r"); done < <(printf '%s\n' "$INFO" | sed -n 's/^run=//p')
FULL=$(printf '%s\n' "$INFO" | sed -n 's/^full=//p')
DRIFT=$(printf '%s\n' "$INFO" | sed -n 's/^drift=//p')
WANT_GB=$(( FULL > 0 ? 3 : 1 ))   # a full cell's evaluation holds about 1.4 GB; the memory cap of #20 will bound it
SCORE_CMD=("$LPY" scripts/studyscore.py)
for r in ${RUNS[@]+"${RUNS[@]}"}; do
  d="$RESULTS/$OUT/$r"
  command -v cygpath >/dev/null 2>&1 && d=$(cygpath -m "$d")
  SCORE_CMD+=("$d")
done
SCORED=""
(( ${#RUNS[@]} )) || { warn "no cell finished, so there is nothing to score."; SCORED=none; }
while (( ${#RUNS[@]} )); do
  GB=$(free_gb)
  if awk -v f="$GB" -v w="$WANT_GB" 'BEGIN {exit !(f >= w)}'; then
    say "Scoring ${#RUNS[@]} run(s) (free RAM ${GB} GB)..."
    if "${SCORE_CMD[@]}"; then SCORED=yes; else warn "scoring failed: see above"; fi
    break
  fi
  warn "only ${GB} GB of RAM is free, and scoring wants ${WANT_GB} GB. Close Chrome or Edge, then press Enter to check again."
  printf '  %ss and Enter skips the scoring:%s ' "$DIM" "$RESET"
  read -r key || key=s
  [[ "$key" == s ]] && break
done
[[ -n "$SCORED" ]] || SKIPPED+=("score later, from study/: ${SCORE_CMD[*]}")
printf '\n'
say "The session's summary (latency in ms):"
printf '%s\n' "$INFO" | sed -n 's/^row=//p' | column -t -s $'\t' | sed 's/^/    /'
note "A run of 200 images is scored only on those images: a plumbing check, never a reported number."
if [[ "$DRIFT" == re-run || "$DRIFT" == unknown ]]; then
  warn "the drift check says $DRIFT: this session's latencies are not trusted, and its cells run again (#8)."
  warn "Copy the plan to a new name, e.g. ${PLAN%.json}-2.json, and run the wizard with it: a new name is a new session."
  SKIPPED+=("run this session's cells again (drift $DRIFT): cp $PLAN ${PLAN%.json}-2.json; bash pi/wizard.sh ${PLAN%.json}-2.json")
fi
[[ "$PLAN" == *pi5-speedtest* ]] && say "Next: the full cell, with  bash pi/wizard.sh plans/pi5-fullcell.json"
next

finish
}

run_wizard "$@"; exit
